        $writes=$this->rows("SELECT * FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='amend_win' AND status NOT IN ('rejected','auth_failed') ORDER BY id DESC",[$origin['id']]);foreach($writes as$index=>$write){$data=json_decode($write['result_json'],true,32,JSON_THROW_ON_ERROR);$intent=ApiReceiptWindow::input($data['window_instruction']??[]);if(($data['window_contract']??null)!==ApiReceiptWindow::CONTRACT||!hash_equals(ApiReceiptWindow::fingerprint($origin,$snapshot,$intent),$data['window_fingerprint']??''))throw new \DomainException('bb_api_receipt_window_corrupt');if(($index===0||$write['status']==='confirmed')&&$observed===$intent['days']){$out['window_id']=(string)$write['id'];if($write['status']==='sending')$out['window_claim_hash']=hash('sha256',$write['claim_token']);return$out;}if($write['status']==='confirmed')throw new \DomainException('bb_api_receipt_window_bank_divergence');}
        if($observed!==$original)throw new \DomainException('bb_api_receipt_window_bank_divergence');return$out;
