    private function confirmReceiptWindow(int$issuer,int$origin,array$result):void
    {
        if(!isset($result['window_id']))return;$id=(int)$result['window_id'];$write=$this->rows("SELECT * FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='amend_win' AND id=? FOR UPDATE",[$origin,$id])[0]??null;if(!$write)throw new \DomainException('bb_api_receipt_window_bank_divergence');$interrupted=$write['status']==='sending'&&$write['locked_until']<=gmdate('Y-m-d H:i:s')&&preg_match('/^[a-f0-9]{64}$/D',$write['claim_token'])&&hash_equals(hash('sha256',$write['claim_token']),$result['window_claim_hash']??'');if(!in_array($write['status'],['validated','unknown','confirmed'],true)&&!$interrupted)throw new \DomainException('bb_api_receipt_window_bank_divergence');
        $data=json_decode($write['result_json'],true,32,JSON_THROW_ON_ERROR);$intent=ApiReceiptWindow::input($data['window_instruction']??[]);[$original,,$snapshot]=$this->loadOrigin($issuer,$origin);if(($data['window_contract']??null)!==ApiReceiptWindow::CONTRACT||!hash_equals(ApiReceiptWindow::fingerprint($original,$snapshot,$intent),$data['window_fingerprint']??''))throw new \DomainException('bb_api_receipt_window_corrupt');if(($result['bank_receipt_window_days']??null)!==$intent['days']||($result['account_scope_confirmed']??null)!=='1'||!preg_match('/^[a-f0-9]{64}$/D',$result['account_evidence_hash']??''))throw new \DomainException('bb_api_receipt_window_bank_divergence');
        $data['bank_state']='window_confirmed';$data['account_evidence_hash']=$result['account_evidence_hash'];$json=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);\IssuerStorage::query($this->db,"UPDATE {$this->prefix}bb_api_operations SET status='confirmed',result_json=?,updated_at=? WHERE id=?",[$json,gmdate('Y-m-d H:i:s'),$id]);$saved=$this->rows("SELECT status,result_json FROM {$this->prefix}bb_api_operations WHERE id=?",[$id])[0]??[];if(($saved['status']??null)!=='confirmed'||($saved['result_json']??null)!==$json)throw new \RuntimeException('issuer_bb_api_write_unconfirmed');
    }
}
